<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('vendor_settlements.view');$pdo=db();
if(input('export')==='1'){require_permission('vendor_settlements.export');header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=vendor-settlements-'.date('Ymd-His').'.csv');$out=fopen('php://output','w');fputcsv($out,['Type','Transaction ID','Vendor','Amount','Destination','Status','Requested At']);foreach($pdo->query("SELECT 'MONEY_REQUEST',r.request_code,v.vendor_code,r.amount,r.destination_reference,r.status,r.requested_at FROM vendor_money_requests r JOIN vendors v ON v.id=r.vendor_id ORDER BY r.requested_at DESC") as $r)fputcsv($out,csv_row($r));foreach($pdo->query("SELECT 'WITHDRAWAL',CONCAT('WD-',r.id),v.vendor_code,r.amount,COALESCE(v.settlement_upi,v.bank_ifsc),r.status,r.requested_at FROM vendor_payout_requests r JOIN vendors v ON v.id=r.vendor_id ORDER BY r.requested_at DESC") as $r)fputcsv($out,csv_row($r));fclose($out);exit;}
if(is_post()){verify_csrf();require_permission('vendor_settlements.approve');try{$action=strtoupper((string)input('action'));$note=trim((string)input('note'));if($action==='REJECT'&&$note==='')throw new InvalidArgumentException('A reason is required when rejecting.');$status=['APPROVE'=>'APPROVED','REJECT'=>'REJECTED','HOLD'=>'HELD'][$action]??null;if(!$status)throw new InvalidArgumentException('Invalid settlement action.');$money=array_map('intval',(array)($_POST['money_ids']??[]));$payout=array_map('intval',(array)($_POST['payout_ids']??[]));$changed=0;if($money){$in=implode(',',array_fill(0,count($money),'?'));$x=$pdo->prepare("UPDATE vendor_money_requests SET status=?,admin_note=?,processed_by=?,processed_at=NOW() WHERE status IN ('PENDING','UNDER_REVIEW') AND id IN ($in)");$x->execute(array_merge([$status,$note?:null,admin()['id']],$money));$changed+=(int)$pdo->query('SELECT ROW_COUNT()')->fetchColumn();foreach($money as $id)audit_log((int)admin()['id'],'VENDOR_MONEY_'.$action,'vendor_money_requests',(string)$id,['note'=>$note]);}if($payout){$in=implode(',',array_fill(0,count($payout),'?'));$x=$pdo->prepare("UPDATE vendor_payout_requests SET status=?,paid_at=CASE WHEN ?='PAID' THEN NOW() ELSE paid_at END WHERE status='PENDING' AND id IN ($in)");$x->execute(array_merge([$status,$status],$payout));$changed+=(int)$pdo->query('SELECT ROW_COUNT()')->fetchColumn();foreach($payout as $id)audit_log((int)admin()['id'],'VENDOR_WITHDRAWAL_'.$action,'vendor_payout_requests',(string)$id,['note'=>$note]);}flash('success',$changed.' eligible settlement record(s) updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/vendors/settlements.php');}
$q=trim((string)input('q'));$status=(string)input('status');$where=[];$params=[];if($q!==''){$where[]='(v.vendor_code LIKE ? OR v.shop_name LIKE ? OR v.name LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');}if(in_array($status,['PENDING','UNDER_REVIEW','APPROVED','PROCESSING','SETTLED','PAID','REJECTED','HELD','FAILED','DISPUTED'],true)){$where[]='x.status=?';$params[]=$status;}$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM vendor_money_requests WHERE status IN ('PENDING','UNDER_REVIEW')) pending_money,(SELECT COALESCE(SUM(amount),0) FROM vendor_money_requests) money_total,(SELECT COUNT(*) FROM vendor_payout_requests WHERE status IN ('PENDING','UNDER_REVIEW')) pending_withdrawals,(SELECT COALESCE(SUM(amount),0) FROM vendor_payout_requests) withdrawal_total,(SELECT COALESCE(SUM(amount),0) FROM vendor_money_requests WHERE status IN ('APPROVED','SETTLED')) approved_money")->fetch();$w=$where?' WHERE '.implode(' AND ',$where):'';$m=$pdo->prepare('SELECT r.id,r.request_code code,r.amount,r.destination_type,r.destination_reference,r.status,r.requested_at,r.admin_note,v.vendor_code,v.name vendor_name,v.shop_name FROM vendor_money_requests r JOIN vendors v ON v.id=r.vendor_id'.($where?' WHERE '.implode(' AND ',array_map(fn($x)=>str_replace('x.status','r.status',$x),$where)): '').' ORDER BY r.requested_at DESC');$m->execute($params);$moneyRows=$m->fetchAll();$p=$pdo->prepare('SELECT r.id,CONCAT("WD-",r.id) code,r.amount,r.status,r.requested_at,r.paid_at,v.vendor_code,v.name vendor_name,v.shop_name,v.bank_account_holder,v.bank_account_number,v.bank_ifsc,v.settlement_upi FROM vendor_payout_requests r JOIN vendors v ON v.id=r.vendor_id'.($where?' WHERE '.implode(' AND ',array_map(fn($x)=>str_replace('x.status','r.status',$x),$where)): '').' ORDER BY r.requested_at DESC');$p->execute($params);$payoutRows=$p->fetchAll();$pageTitle='Vendor money requests & withdrawals';$pageSubtitle='Separate vendor funding requests from earnings settlement payouts';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="panel-head"><div><h2>Vendor financial settlement control</h2><p class="help">Money Requests and Withdrawals are processed as separate workflows.</p></div><?php if(can('vendor_settlements.export')):?><a class="btn secondary" href="?<?=http_build_query(['q'=>$q,'status'=>$status,'export'=>1])?>">Export Excel / CSV</a><?php endif?></div><div class="grid stats"><div class="card"><span class="label">Total money requests</span><span class="value"><?=money($stats['money_total'])?> (<?=e((int)$stats['pending_money'])?> pending)</span></div><div class="card"><span class="label">Total withdrawals</span><span class="value"><?=money($stats['withdrawal_total'])?> (<?=e((int)$stats['pending_withdrawals'])?> pending)</span></div><div class="card"><span class="label">Settlement approved</span><span class="value"><?=money($stats['approved_money'])?></span></div><div class="card"><span class="label">Pending approvals</span><span class="value"><?=e((int)$stats['pending_money']+(int)$stats['pending_withdrawals'])?></span></div></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Vendor ID, name or shop"><select name="status"><option value="">All statuses</option><?php foreach(['PENDING','UNDER_REVIEW','APPROVED','PROCESSING','SETTLED','PAID','REJECTED','HELD','FAILED','DISPUTED'] as $s):?><option <?=selected($status,$s)?>><?=$s?></option><?php endforeach?></select><button class="btn">Filter</button></form><form method="post"><?=csrf_field()?><div class="actions" style="margin-bottom:12px"><button class="btn success" name="action" value="APPROVE">Approve selected payments</button><button class="btn danger" name="action" value="REJECT" onclick="return settlementReason()">Reject selected</button><button class="btn secondary" name="action" value="HOLD">Hold selected</button><input name="note" id="settlement-note" placeholder="Reason / approval note"></div><div class="grid detail-grid"><section><h2>Vendor Money Requests</h2><div class="table-wrap"><table><thead><tr><th></th><th>Transaction</th><th>Vendor / business</th><th>Amount</th><th>Destination</th><th>Status</th><th>Requested</th></tr></thead><tbody><?php foreach($moneyRows as $r):?><tr><td><input type="checkbox" name="money_ids[]" value="<?=e($r['id'])?>"></td><td><?=e($r['code'])?></td><td><?=e($r['vendor_name'])?><br><small><?=e($r['shop_name'])?></small></td><td><?=money($r['amount'])?></td><td><?=e($r['destination_type'])?><br><small><?=e($r['destination_reference']?:'—')?></small></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['requested_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$moneyRows):?><div class="empty">No vendor money requests.</div><?php endif?></div></section><section><h2>Vendor Withdrawal Requests</h2><div class="table-wrap"><table><thead><tr><th></th><th>Transaction</th><th>Vendor / business</th><th>Amount</th><th>Destination</th><th>Status</th><th>Requested</th></tr></thead><tbody><?php foreach($payoutRows as $r):?><tr><td><input type="checkbox" name="payout_ids[]" value="<?=e($r['id'])?>"></td><td><?=e($r['code'])?></td><td><?=e($r['vendor_name'])?><br><small><?=e($r['shop_name'])?></small></td><td><?=money($r['amount'])?></td><td><?=e(mask_account($r['bank_account_number']??null))?><br><small><?=e($r['settlement_upi']?:$r['bank_ifsc']?:'—')?></small></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['requested_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$payoutRows):?><div class="empty">No vendor withdrawals.</div><?php endif?></div></section></div></form></section><script>function settlementReason(){if(!document.getElementById('settlement-note').value.trim()){alert('Enter a reason before rejecting.');return false}return true}</script><?php require APP_ROOT.'/includes/footer.php';
